/**
 * iPin InfiniteScroll  v1.0.0
 * Automatically fetches the next page of results when the user
 * scrolls near the bottom of the grid and appends the new items.
 *
 * API surface matches the Infinite Scroll / jquery.infinitescroll plugin
 * so existing call-sites work unchanged:
 *
 *   $(grid).infinitescroll({
 *     navSelector:  '#navigation',
 *     nextSelector: '#navigation-next a',
 *     itemSelector: '.thumb',
 *     loading: {
 *       msgText:     '<em>Loading…</em>',
 *       finishedMsg: '<em>All items loaded</em>',
 *     },
 *     errorCallback: function() {},
 *   }, function(newElements) {
 *     // callback receives raw DOM nodes of newly added items
 *   });
 *
 * Written from scratch for iPin Modern.
 * No external dependencies beyond jQuery.
 */
;(function ($) {
  'use strict';

  // ─────────────────────────────────────────────────────
  //  Shared state
  // ─────────────────────────────────────────────────────

  /** Pixels from the bottom of the page to trigger a fetch. */
  var TRIGGER_OFFSET = 300;

  /** How many ms to wait between scroll events before acting. */
  var SCROLL_DEBOUNCE = 120;

  /** Per-element state map: element → { opts, callback, state } */
  var registry = [];

  function getEntry(el) {
    for (var i = 0; i < registry.length; i++) {
      if (registry[i].el === el) return registry[i];
    }
    return null;
  }


  // ─────────────────────────────────────────────────────
  //  Loading indicator
  // ─────────────────────────────────────────────────────

  var $indicator = null;

  function ensureIndicator() {
    if (!$indicator) {
      $indicator = $('<div id="infscr-loading" style="text-align:center;padding:20px 0;">')
        .appendTo('body')
        .hide();
    }
    return $indicator;
  }

  function showLoading(msgHtml) {
    ensureIndicator().html(msgHtml).fadeIn(200);
  }

  function hideLoading() {
    if ($indicator) $indicator.fadeOut(200);
  }

  function showFinished(msgHtml) {
    ensureIndicator()
      .html(msgHtml)
      .fadeIn(200);
  }


  // ─────────────────────────────────────────────────────
  //  Next-page URL resolution
  // ─────────────────────────────────────────────────────

  /**
   * Find the URL for the next page.
   * Reads the href of the element matched by `nextSelector`.
   *
   * @param  {string} nextSelector   CSS selector for the "next" link
   * @returns {string|null}
   */
  function resolveNextUrl(nextSelector) {
    var $next = $(nextSelector).first();
    if (!$next.length) return null;
    return $next.attr('href') || null;
  }


  // ─────────────────────────────────────────────────────
  //  Fetcher
  // ─────────────────────────────────────────────────────

  /**
   * Fetch `url`, extract items matching `itemSelector`, and call
   * `onSuccess(newDomNodes)` — or `onError()` if the request fails.
   *
   * Also extracts the next-page link from the fetched page and
   * updates the current next-selector element's href so subsequent
   * fetches advance one page further.
   *
   * @param {string}   url
   * @param {string}   itemSelector
   * @param {string}   nextSelector    selector for the "next" link in *current* page
   * @param {Function} onSuccess
   * @param {Function} onError
   */
  function fetchPage(url, itemSelector, nextSelector, onSuccess, onError) {
    $.ajax({
      url:      url,
      dataType: 'html',
      success: function (html) {
        // Parse the fetched HTML into a detached document fragment.
        var $remote = $('<div>').html(html);

        // Extract new items.
        var $items = $remote.find(itemSelector);

        if (!$items.length) {
          onError('no-items');
          return;
        }

        // Advance the next-page link on the current page so the next
        // fetch will request page N+2 rather than N+1 again.
        var $remoteNext = $remote.find(nextSelector.replace(/^[^#\[]+/, ''));
        if (!$remoteNext.length) {
          // Try a broader match — strip ancestor context from selector
          $remoteNext = $remote.find('a[rel="next"], .next a, [class*="next"] a').first();
        }
        if ($remoteNext.length) {
          var newHref = $remoteNext.attr('href');
          if (newHref) {
            $(nextSelector).attr('href', newHref);
          }
        } else {
          // No next link in fetched page → this was the last page.
          // Remove the next selector so subsequent scroll events stop.
          $(nextSelector).removeAttr('href');
        }

        onSuccess($items.get());  // pass raw DOM nodes
      },
      error: function () {
        onError('network');
      },
    });
  }


  // ─────────────────────────────────────────────────────
  //  Scroll handler
  // ─────────────────────────────────────────────────────

  var scrollTimer = null;

  function onScroll() {
    clearTimeout(scrollTimer);
    scrollTimer = setTimeout(checkAll, SCROLL_DEBOUNCE);
  }

  /**
   * Walk all registered instances and trigger a fetch for any that
   * are near the bottom and not already loading.
   */
  function checkAll() {
    var scrollBottom = $(window).scrollTop() + $(window).height();
    var docHeight    = $(document).height();

    if (scrollBottom < docHeight - TRIGGER_OFFSET) return;

    for (var i = 0; i < registry.length; i++) {
      var entry = registry[i];
      if (entry.state.loading || entry.state.finished) continue;
      triggerFetch(entry);
    }
  }

  /**
   * Trigger one page fetch for an entry.
   *
   * @param {{ el, opts, callback, state }} entry
   */
  function triggerFetch(entry) {
    var opts     = entry.opts;
    var loading  = opts.loading || {};

    var nextUrl = resolveNextUrl(opts.nextSelector);
    if (!nextUrl) {
      // No next link — we've reached the end.
      entry.state.finished = true;
      hideLoading();
      showFinished(loading.finishedMsg || '<em>All items loaded</em>');
      // Remove the nav element from the DOM (keeps pagination clean).
      $(opts.navSelector).remove();
      return;
    }

    entry.state.loading = true;
    showLoading(loading.msgText || '<em>Loading…</em>');

    fetchPage(
      nextUrl,
      opts.itemSelector,
      opts.nextSelector,
      function (newNodes) {
        // Append new items to the container.
        var $new = $(newNodes);
        $(entry.el).append($new);

        hideLoading();
        entry.state.loading = false;

        // Fire the user callback with the raw nodes.
        if (typeof entry.callback === 'function') {
          entry.callback(newNodes);
        }

        // If the next selector no longer has an href, we're done.
        if (!resolveNextUrl(opts.nextSelector)) {
          entry.state.finished = true;
          showFinished(loading.finishedMsg || '<em>All items loaded</em>');
          $(opts.navSelector).remove();
        }
      },
      function (reason) {
        entry.state.loading = false;
        hideLoading();
        if (reason === 'no-items') {
          // Treat as last page.
          entry.state.finished = true;
          showFinished(loading.finishedMsg || '<em>All items loaded</em>');
          $(opts.navSelector).remove();
        }
        if (typeof opts.errorCallback === 'function') {
          opts.errorCallback(reason);
        }
      }
    );
  }

  // Attach single shared scroll listener.
  $(window).on('scroll.ipinInfiniteScroll', onScroll);


  // ─────────────────────────────────────────────────────
  //  jQuery plugin interface
  // ─────────────────────────────────────────────────────

  /**
   * $(grid).infinitescroll(options [, callback])
   *
   * @param {Object}   opts      Configuration (see top-of-file docs)
   * @param {Function} callback  Receives an array of new DOM nodes
   */
  $.fn.infinitescroll = function (opts, callback) {
    var defaultOpts = {
      navSelector:   '#navigation',
      nextSelector:  '#navigation-next a',
      itemSelector:  '.thumb',
      loading: {
        msgText:     '<em>Loading…</em>',
        finishedMsg: '<em>All items loaded</em>',
      },
      errorCallback: null,
    };

    var options = $.extend(true, {}, defaultOpts, opts);

    return this.each(function () {
      var existing = getEntry(this);
      if (existing) return;  // already initialised

      // Validate: if there's no next link, there's nothing to do.
      if (!resolveNextUrl(options.nextSelector)) return;

      registry.push({
        el:       this,
        opts:     options,
        callback: typeof callback === 'function' ? callback : null,
        state: {
          loading:  false,
          finished: false,
        },
      });

      // Hide the WP pagination nav — infinite scroll replaces it.
      $(options.navSelector).hide();
    });
  };

}(jQuery));
